            vert = (r > 0 and r+1 < h and grid[r-1][c] == 9 and grid[r+1][c] == 9)
            if horiz or vert:
                out[r][c] = 2
    # Capture any longer runs, whose interior cells are not immediately adjacent to 9.
    for r in range(h):
        c=0
        while c<w:
            if grid[r][c]!=4: c+=1; continue
            s=c
            while c<w and grid[r][c]==4: c+=1
            if s>0 and c<w and grid[r][s-1]==9 and grid[r][c]==9:
                for x in range(s,c): out[r][x]=2
