 "content": "def transform(grid):
    """Replace short 4-valued runs framed by 9s, horizontally or vertically."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Horizontal framed bars are at most six cells in the demonstrated pattern.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 4:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] == 4:
                c += 1
            if c - start <= 6 and start > 0 and c < w and grid[r][start-1] == 9 and grid[r][c] == 9:
                for x in range(start, c):
                    out[r][x] = 2
    # Vertically framed bars; long framed lines in the demo are unchanged.
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 4:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] == 4:
                r += 1
            if r - start <= 3 and start > 0 and r < h and grid[start-1][c] == 9 and grid[r][c] == 9:
                for y in range(start, r):
                    out[y][c] = 2
