    markers = {v for v, count in enumerate(counts) if count and v != background}
    out = [row[:] for row in grid]

    # Along each row/column, connect every consecutive pair of non-background
    # markers of the same color, leaving the marker cells themselves unchanged.
    for r in range(h):
        for color in markers:
            positions = [c for c in range(w) if grid[r][c] == color]
            for a, b in zip(positions, positions[1:]):
