 "content": "def transform(grid):
    """Fill short gaps between same-color marks in rows and columns."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Between markers, recolor background gaps up to three cells long.
    # This matches the short broken-line segments in the dense line-pattern inputs.
    for r in range(h):
        for color in set(grid[r]) - {background}:
            positions = [c for c, value in enumerate(grid[r]) if value == color]
            for a, b in zip(positions, positions[1:]):
                if b - a <= 4:
                    for c in range(a + 1, b):
                        if grid[r][c] == background:
                            out[r][c] = 2
    for c in range(w):
        colors = {grid[r][c] for r in range(h)} - {background}
        for color in colors:
            positions = [r for r in range(h) if grid[r][c] == color]
            for a, b in zip(positions, positions[1:]):
                if b - a <= 4:
                    for r in range(a + 1, b):
                        if grid[r][c] == background:
                            out[r][c] = 2
    return out

if __name__ == '__main__':
